INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7684, NULL, '2026-11-03 17:17:56.322257', 'Chủ đầu tư Sun Property bàn giao những căn Casa Villa đầu tiên, hướng tới mục tiêu hoàn tất hơn 400 căn thấp tầng, hình thành nhịp sống mới tại Blanca City.', 'https://i1-vnexpress.vnecdn.net/2026/11/02/su-kien-ban-giao-nha-phan-khu-6040-3433-1793626800.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=QeLqTVLUbxaVd6CSirtSHw', '2026-11-03 01:00:00', 'Bàn giao phân khu thấp tầng Casa Villa thuộc Blanca City', 'https://vnexpress.net/ban-giao-phan-khu-thap-tang-casa-villa-thuoc-blanca-city-5139900.html', 919, 9, 'https://vnexpress.net/ban-giao-phan-khu-thap-tang-casa-villa-thuoc-blanca-city-5139900.html', 'CRAWLER', '2026-11-03 17:19:16.41856', '2026-11-03 17:19:16.41856');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7686, NULL, '2026-11-03 17:17:57.050349', 'Người mua Diamond Sky có cơ hội nhận thêm một căn hộ trị giá gần 8 tỷ đồng trong chương trình "Mua nhà trúng nhà - Nhân đôi tổ ấm" của Van Phuc Group, diễn ra từ nay đến 1/11/2027.', 'https://i1-vnexpress.vnecdn.net/2026/11/02/hinh-1793608883-4789-1793609332.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=yxOvo9nmjNR03sw4PBPPrw', '2026-11-03 01:00:00', 'Van Phuc Group tặng căn hộ gần 8 tỷ đồng cho người mua Diamond Sky', 'https://vnexpress.net/van-phuc-group-tang-can-ho-gan-8-ty-dong-cho-nguoi-mua-diamond-sky-5139676.html', 919, 9, 'https://vnexpress.net/van-phuc-group-tang-can-ho-gan-8-ty-dong-cho-nguoi-mua-diamond-sky-5139676.html', 'CRAWLER', '2026-11-03 17:19:16.42156', '2026-11-03 17:19:16.42156');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7689, NULL, '2026-11-03 17:17:57.592677', 'Khách hàng hiện có thể đổi điểm tích lũy trên ứng dụng Long Châu thành tiền hỗ trợ bệnh nhân ung thư có hoàn cảnh khó khăn, thông qua Quỹ Hy vọng.', 'https://i1-giadinh.vnecdn.net/2026/11/02/a-nh-ma-n-hi-nh-lu-c-179359921-2274-9986-1793599281.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=6TfxQbkHAHGB-vbpAEth6Q', '2026-11-03 00:56:27', 'Đổi điểm thưởng hỗ trợ viện phí cho bệnh nhân ung thư', 'https://vnexpress.net/doi-diem-thuong-ho-tro-vien-phi-cho-benh-nhan-ung-thu-5139712.html', 989, 9, 'https://vnexpress.net/doi-diem-thuong-ho-tro-vien-phi-cho-benh-nhan-ung-thu-5139712.html', 'CRAWLER', '2026-11-03 17:19:23.553593', '2026-11-03 17:19:23.553593');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7683, NULL, '2026-11-03 17:17:55.865407', 'Đây là khoảnh khắc kịch tính khi một chú chó can thiệp để ngăn chặn cuộc chiến giữa hai con mèo trên đường phố ở Chiết Giang, Trung Quốc.', 'https://i1-vnexpress.vnecdn.net/2026/11/02/tixung-1793608287-1432-1793609286.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=g4yLKIsq18xZNPdHpri6jQ&t=image', '2026-11-03 01:00:00', 'Cún cưng lao vào can ngăn cuộc ẩu đả giữa hai con mèo', 'https://vnexpress.net/cun-cung-lao-vao-can-ngan-cuoc-au-da-giua-hai-con-meo-5139810.html', 1329, 9, 'https://vnexpress.net/cun-cung-lao-vao-can-ngan-cuoc-au-da-giua-hai-con-meo-5139810.html', 'CRAWLER', '2026-11-03 17:20:26.22522', '2026-11-03 17:20:26.22522');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7692, '<h1>Quan chức Nga, Mỹ, Ukraine sắp gặp ba bên</h1>
<p>Các quan chức Nga, Mỹ, Ukraine sẽ tổ chức cuộc họp ba bên vào tuần tới tại UAE để thúc đẩy các cuộc đàm phán hòa bình.</p>
<p>"Mỹ sẽ làm trung gian cho các cuộc đàm phán cấp chuyên viên giữa Ukraine và Nga vào ngày 10-11/11 tại Abu Dhabi, nhằm thúc đẩy sứ mệnh chấm dứt chiến sự của Tổng thống Trump", ông Steve Witkoff, đặc phái viên của Tổng thống Donald Trump, viết trên mạng xã hội X ngày 2/11.</p>
<p>Các cuộc thảo luận sẽ tập trung vào thỏa thuận an ninh thời hậu chiến, giảm leo thang căng thẳng, các nỗ lực nhân đạo và những bước tiếp theo hướng tới hòa bình. Witkoff cho biết thêm rằng các nhà đàm phán Mỹ cũng sẽ gặp gỡ các quan chức châu Âu và NATO tại Brussels, Bỉ, trong tuần này.</p>
<p>Một quan chức Mỹ cấp cao tiết lộ với <em>Reuters </em>rằng đặc phái viên Witkoff cùng con rể ông Trump là Jared Kushner sẽ đại diện cho Washington trong cuộc gặp tại Abu Dhabi.</p>
<figure>
 <div>
  <img alt="Ông Steve Witkoff tại Riyadh, Arab Saudi, hồi tháng 2/2025. Ảnh: AP" src="https://i1-vnexpress.vnecdn.net/2026/11/03/witkoff-6665-1793664312.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=wfqWO-im-7QQEoZchib50w">
 </div>
 <figcaption>
  <p>Ông Steve Witkoff tại Riyadh, Arab Saudi, hồi tháng 2/2025. Ảnh: <em>AP</em></p>
 </figcaption>
</figure>
<p>Quan chức này cũng tiết lộ thêm rằng các nhà đàm phán Mỹ sẽ họp cấp chuyên viên tại Brussels với đại diện từ Pháp, Đức, Anh, Liên minh châu Âu (EU) và NATO để thảo luận về "các bảo đảm an ninh cho Ukraine, khuôn khổ an ninh tương lai của châu Âu, cũng như hỗ trợ kinh tế cho công cuộc tái thiết Ukraine".</p>
<p>Theo quan chức này, các cuộc họp được xây dựng dựa trên những thảo luận gần đây giữa các bên, đồng thời "phản ánh nỗ lực không ngừng của Tổng thống Trump nhằm đạt được một thỏa thuận hòa bình lâu dài giữa Nga và Ukraine".</p>
<p>Kiev và Moskva chưa phản hồi về thông tin, nhưng trước đó đều thể hiện quan điểm cởi mở về đàm phán ba bên. Cách đây hai tuần, Tổng thống Nga Vladimir Putin đã tiếp đặc phái viên Mỹ Witkoff tại St. Petersburg.</p>
<figure>
 <div>
  <img alt="Hai đặc phái viên Mỹ Jared Kushner (trái) và Steve Witkoff tại Kiev ngày 6/9. Ảnh: AFP" src="https://i1-vnexpress.vnecdn.net/2026/11/03/AFP-20260906-C7H37YK-v3-HighRe-3409-2423-1793664312.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=AHcBQt9BTQIoEjaeWLx22w">
 </div>
 <figcaption>
  <p>Hai nhà đàm phán Mỹ Jared Kushner (trái) và Steve Witkoff tại Kiev ngày 6/9. Ảnh: <em>AFP</em></p>
 </figcaption>
</figure>
<p>Tuy nhiên, Nga và Ukraine vẫn còn bất đồng sâu sắc về các điều khoản cho bất kỳ thỏa thuận hòa bình tiềm năng nào, bất chấp Tổng thống Trump gần đây gia tăng áp lực với Ukraine.</p>
<p><strong>Ngọc Ánh</strong> (Theo<em> AFP, Reuters</em>)</p><!-- Hope --> <!-- End Hope -->', '2026-11-03 17:17:59.299079', 'Các quan chức Nga, Mỹ, Ukraine sẽ tổ chức cuộc họp ba bên vào tuần tới tại UAE để thúc đẩy các cuộc đàm phán hòa bình.', 'https://i1-vnexpress.vnecdn.net/2026/11/03/witkoff-1793664279-5817-1793664313.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=VVutiHnz87uOQ67CZa5MqA', '2026-11-03 00:17:43', 'Quan chức Nga, Mỹ, Ukraine sắp gặp ba bên', 'https://vnexpress.net/quan-chuc-nga-my-ukraine-sap-gap-ba-ben-5139947.html', 496, 9, 'https://vnexpress.net/quan-chuc-nga-my-ukraine-sap-gap-ba-ben-5139947.html', 'CRAWLER', '2026-11-03 17:17:59.299079', '2026-11-03 17:17:59.299079');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7559, NULL, '2026-11-03 17:17:12.228089', 'Người bệnh hưởng bảo hiểm y tế mức 80%, 95% hay 100% chỉ được chi trả trong phạm vi và danh mục quỹ quy định, không phải toàn bộ hóa đơn viện phí.', 'https://i1-suckhoe.vnecdn.net/2026/11/02/khambenh-1793615530-4845-1793615628.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=YYNu73Pe3wrsb1NvztoRLw', '2026-11-03 00:00:00', 'Vì sao hưởng bảo hiểm y tế 100% vẫn phải trả thêm tiền?', 'https://vnexpress.net/vi-sao-huong-bao-hiem-y-te-100-van-phai-tra-them-tien-5139881.html', 1657, 9, 'https://vnexpress.net/vi-sao-huong-bao-hiem-y-te-100-van-phai-tra-them-tien-5139881.html', 'CRAWLER', '2026-11-03 17:17:59.304079', '2026-11-03 17:17:59.304079');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7696, '<h1>Triều Tiên đáp trả cáo buộc ''tấn công mạng Binance'' từ FBI</h1>
<p>Triều Tiên gọi cáo buộc của FBI rằng nước này đứng sau vụ đánh cắp hơn 6 tỷ USD từ nền tảng tiền mã hóa Binance là "hành vi khiêu khích nghiêm trọng".</p>
<p>Trong tuyên bố được hãng thông tấn trung ương Triều Tiên <em>KCNA </em>phát đi hôm nay, bà Kim Yo-jong, em gái lãnh đạo Triều Tiên Kim Jong-un, chỉ trích cáo buộc của Cục Điều tra Liên bang Mỹ (FBI) là "luận điệu nhảm nhí và không có gì mới mẻ". Bà viện dẫn cáo buộc trước đó từ Mỹ cho rằng Triều Tiên đứng sau vụ tấn công mạng quy mô lớn nhằm vào sàn tiền số Bybit hồi năm ngoái.</p>
<p>"Việc Mỹ thao túng dư luận quốc tế, đổ lỗi cho chúng tôi về mọi cuộc tấn công mạng trên thế giới là hành vi khiêu khích chính trị nghiêm trọng nhắm vào Triều Tiên", bà nhấn mạnh.</p>
<p>FBI cuối tuần trước cho biết một nhóm hacker có liên hệ với Triều Tiên mang tên TraderTraitor là thủ phạm đứng sau vụ tấn công mạng, đánh cắp 6,3 tỷ USD từ Binance hôm 29/10. Đây được đánh giá là vụ hack có quy mô lớn nhất trong lịch sử các sàn tiền số.</p>
<p>"Đây là âm mưu nguy hiểm nhằm bôi nhọ hình ảnh quốc tế của Triều Tiên, xúc phạm đến phẩm giá cũng như uy tín quốc gia của chúng tôi, đồng thời là một hành động xâm phạm nghiêm trọng khác đối với chủ quyền của Triều Tiên", bà Kim cho hay. "Triều Tiên kiên quyết phản đối mọi hành vi độc hại trên không gian mạng".</p>
<figure>
 <div>
  <img alt="Bà Kim Yo-jong phát biểu tại Bình Nhưỡng, Triều Tiên, tháng 8/2022. Ảnh: AFP" src="https://i1-vnexpress.vnecdn.net/2026/11/03/AFP-20220814-32GH2H8-v1-HighRe-4944-3157-1793662361.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=V8ljRgnNDMjSlBMYVBW3zA">
 </div>
 <figcaption>
  <p>Bà Kim Yo-jong phát biểu tại Bình Nhưỡng, Triều Tiên, tháng 8/2022. Ảnh: <em>AFP</em></p>
 </figcaption>
</figure>
<p>Binance là sàn tiền mã hóa lớn nhất thế giới tính theo khối lượng giao dịch hàng ngày. Thông tin về vụ tấn công mạng đã khiến giá của hầu hết các đồng tiền số giảm mạnh hồi cuối tuần trước.</p>
<p>Sau khi FBI công bố đánh giá của mình hôm 31/10, Tổng thống Donald Trump đã tỏ ra hoài nghi về khả năng Triều Tiên liên quan đến vụ tấn công mạng này.</p>
<p>"Tôi không lo ngại. Chúng tôi đang tìm hiểu sự việc. Vẫn chưa thể khẳng định liệu Triều Tiên có đứng sau chuyện đó hay không", ông phát biểu trước báo giới tại dinh thự riêng ở Florida.</p>
<p>Kể từ khi trở lại Nhà Trắng, Tổng thống Trump liên tục phát đi tín hiệu hòa giải tới Bình Nhưỡng, đồng thời ngỏ ý sẵn sàng gặp lãnh đạo Triều Tiên Kim Jong-un. Song đến nay, Triều Tiên vẫn im lặng trước những động thái này.</p>
<p>Bà Kim Yo-jong khẳng định những cáo buộc mới "một lần nữa xác nhận thái độ thù địch của Mỹ với Triều Tiên". "Chúng tôi có những vấn đề cần xem xét lại trên nhiều khía cạnh liên quan tới thái độ thù địch rất khó chịu này của Mỹ", bà nói.</p>
<figure>
 <div>
  <img alt="Logo của Binance, sàn tiền mã hóa lớn nhất thế giới tính theo khối lượng giao dịch hàng ngày. Ảnh: Reuters" src="https://i1-vnexpress.vnecdn.net/2026/11/03/anh2-jpeg-1793662138-7375-1793662361.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=Yz-CFWQXyVq1y0Bs-G9r0Q">
 </div>
 <figcaption>
  <p>Logo của Binance, sàn tiền mã hóa lớn nhất thế giới tính theo khối lượng giao dịch hàng ngày. Ảnh: <em>Reuters</em></p>
 </figcaption>
</figure>
<p><strong>Vũ Hoàng </strong>(Theo <em>AFP, Reuters, AP</em>)</p><!-- Hope --> <!-- End Hope -->', '2026-11-03 17:18:00.135598', 'Triều Tiên gọi cáo buộc của FBI rằng nước này đứng sau vụ đánh cắp hơn 6 tỷ USD từ nền tảng tiền mã hóa Binance là "hành vi khiêu khích nghiêm trọng".', 'https://i1-vnexpress.vnecdn.net/2026/11/03/AFP-20240326-34M78WA-v1-HighRe-9067-8822-1793662361.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=JEnqM2S4mJqv-0c7QGb5jQ', '2026-11-02 23:48:08', 'Triều Tiên đáp trả cáo buộc ''tấn công mạng Binance'' từ FBI', 'https://vnexpress.net/trieu-tien-dap-tra-cao-buoc-tan-cong-mang-binance-tu-fbi-5139936.html', 496, 9, 'https://vnexpress.net/trieu-tien-dap-tra-cao-buoc-tan-cong-mang-binance-tu-fbi-5139936.html', 'CRAWLER', '2026-11-03 17:18:00.135598', '2026-11-03 17:18:00.135598');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7695, NULL, '2026-11-03 17:17:59.867896', 'Tay đấm bất bại Floyd Mayweather thông báo sẽ thượng đài với Matty Floyd, võ sĩ từng làm vũ công thoát y và ngồi tù, tại Bangkok ngày 19/12.', 'https://i1-thethao.vnecdn.net/2026/11/02/may-1793622379-5575-1793622394.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=ol1GSq0M6LZw3wFrPSyPmA', '2026-11-02 23:49:52', 'Mayweather đấu cựu vũ công thoát y tại Thái Lan', 'https://vnexpress.net/mayweather-dau-cuu-vu-cong-thoat-y-tai-thai-lan-5139897.html', 663, 9, 'https://vnexpress.net/mayweather-dau-cuu-vu-cong-thoat-y-tai-thai-lan-5139897.html', 'CRAWLER', '2026-11-03 17:18:03.615854', '2026-11-03 17:18:03.615854');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7698, NULL, '2026-11-03 17:18:00.633436', 'HLV Michael Carrick phủ nhận cảm giác chỉ còn hai trận để cứu công việc ở Man Utd, đồng thời khẳng định không nghi ngờ sự tận tâm của các cầu thủ.', 'https://i1-thethao.vnecdn.net/2026/11/02/a-nh-ma-n-hi-nh-lu-c-179363560-6021-5684-1793636239.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=4Re-5fJ0H6eCJ2d3L4tv0A', '2026-11-02 23:29:24', 'Carrick không tin chỉ còn hai trận để giữ ghế ở Man Utd', 'https://vnexpress.net/carrick-khong-tin-chi-con-hai-tran-de-giu-ghe-o-man-utd-5139928.html', 663, 9, 'https://vnexpress.net/carrick-khong-tin-chi-con-hai-tran-de-giu-ghe-o-man-utd-5139928.html', 'CRAWLER', '2026-11-03 17:18:03.619852', '2026-11-03 17:18:03.619852');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7699, NULL, '2026-11-03 17:18:00.818814', 'Cristiano Ronaldo và Lionel Messi góp mặt trong danh sách 26 ứng viên cho Đội hình hay nhất năm 2026 của FIFPRO, do gần 20.000 cầu thủ chuyên nghiệp trên toàn thế giới bình chọn.', 'https://i1-thethao.vnecdn.net/2026/11/02/ronaldo-mu-ng-ba-n-1793637402-8006-1793637518.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=glQ2qWTnbxq0s6ysUyQouw', '2026-11-02 23:22:15', 'Ronaldo và Messi được đề cử vào Đội hình hay nhất năm 2026', 'https://vnexpress.net/ronaldo-va-messi-duoc-de-cu-vao-doi-hinh-hay-nhat-nam-2026-5139931.html', 663, 9, 'https://vnexpress.net/ronaldo-va-messi-duoc-de-cu-vao-doi-hinh-hay-nhat-nam-2026-5139931.html', 'CRAWLER', '2026-11-03 17:18:03.622849', '2026-11-03 17:18:03.622849');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7693, NULL, '2026-11-03 17:17:59.420241', 'Nhiều khách hàng phát hiện có mã QR cửa hàng đứng tên mình trên ứng dụng MB, nhà băng nói đây là tính năng hỗ trợ nhận thanh toán, theo dõi giao dịch, không đồng nghĩa khách được đăng ký hộ kinh doanh.', 'https://i1-kinhdoanh.vnecdn.net/2026/10/30/wm1-wm1-thong-tin-cua-hang-tren-di-3632-8768-1793371059.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=DYS1vG7YvuFqdJB88coCvQ', '2026-11-03 00:00:00', 'Loạt chủ tài khoản bỗng dưng có mã QR hộ kinh doanh', 'https://vnexpress.net/loat-chu-tai-khoan-bong-dung-co-ma-qr-ho-kinh-doanh-5138920.html', 712, 9, 'https://vnexpress.net/loat-chu-tai-khoan-bong-dung-co-ma-qr-ho-kinh-doanh-5138920.html', 'CRAWLER', '2026-11-03 17:18:21.74295', '2026-11-03 17:18:21.74295');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7701, NULL, '2026-11-03 17:18:01.452726', 'Khoảng một tuần qua, nhiều người tìm đến các ứng dụng đi chùa ảo để giải tỏa căng thẳng, tạo nên trào lưu mô phỏng tâm linh thu hút hàng chục nghìn lượt truy cập.', 'https://i1-giadinh.vnecdn.net/2026/11/03/a-nh-ma-n-hi-nh-lu-1793638841-8067-1793638855.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=Yo1DjyTxRpZASVXYBVDBTw', '2026-11-02 23:00:00', 'Đi chùa online', 'https://vnexpress.net/di-chua-online-5139873.html', 989, 9, 'https://vnexpress.net/di-chua-online-5139873.html', 'CRAWLER', '2026-11-03 17:19:23.35362', '2026-11-03 17:19:23.35362');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7694, NULL, '2026-11-03 17:17:59.703241', 'Lấy cảm hứng từ ba mũi thuyền, tháp Tam Thắng bên bờ biển Bãi Sau nhanh chóng trở thành điểm thu hút khách ở Vũng Tàu sau hơn một năm xây dựng.', 'https://i1-vnexpress.vnecdn.net/2026/10/30/dji-1793361967.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=5srG8LHdKF_mWgy1xw1D6w', '2026-11-03 00:00:00', 'Tháp Tam Thắng hút khách check in bên biển Vũng Tàu', 'https://vnexpress.net/thap-tam-thang-hut-khach-check-in-ben-bien-vung-tau-5137329.html', 1028, 9, 'https://vnexpress.net/thap-tam-thang-hut-khach-check-in-ben-bien-vung-tau-5137329.html', 'CRAWLER', '2026-11-03 17:19:34.048234', '2026-11-03 17:19:34.048234');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7700, NULL, '2026-11-03 17:18:01.041099', 'Một cuộc tấn công mạng đang lan khắp các siêu thị ở châu Âu, khi tủ lạnh và tủ đông bị tăng nhiệt vào nửa đêm, khiến cửa hàng buộc phải tiêu hủy thực phẩm.', 'https://i1-vnexpress.vnecdn.net/2026/11/03/hack-jpeg-1793661497-6205-1793661554.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=QBiLS-XECutJs02bNbrrDw', '2026-11-02 23:12:46', 'Hacker tăng nhiệt tủ lạnh đến 50 độ C tại hàng loạt siêu thị châu Âu', 'https://vnexpress.net/hacker-tang-nhiet-tu-lanh-den-50-do-c-tai-hang-loat-sieu-thi-chau-au-5139939.html', 1111, 9, 'https://vnexpress.net/hacker-tang-nhiet-tu-lanh-den-50-do-c-tai-hang-loat-sieu-thi-chau-au-5139939.html', 'CRAWLER', '2026-11-03 17:19:46.357371', '2026-11-03 17:19:46.357371');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7702, '<div>
 <h1>Những hộ dân cuối dỡ nhà thi công nút giao lớn nhất TP HCM</h1><!--  pinbar menu title -->
 <div>
  <div>
   <div>
    <h2><span> Những hộ dân cuối dỡ nhà thi công nút giao lớn nhất TP HCM</span></h2>
   </div>
  </div>
 </div><!--  end pinbar menu title  -->
 <p>Hơn 60 hộ trên đường Lương Định Của tháo dỡ, bàn giao mặt bằng để mở rộng đường và thi công cầu vượt ở nút giao An Phú.</p>
</div>
<div width="5472">
 <div>
  <div>
   <img alt="" src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-dji-1793601970-1793602270.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=O3s53ea0FnMuX9TjXhtktg">
  </div>
  <div>
   <p>Hơn một tuần nay, nhiều căn nhà trên đường Lương Định Của, đoạn từ giao lộ với đường Nguyễn Hoàng đến đại lộ Mai Chí Thọ tiến hành tháo dỡ. Đây là những hộ cuối bàn giao mặt bằng để mở rộng đường Lương Định của và thi công nút giao An Phú.</p>
   <p>Trước đó, dự án đường Lương Định Của kéo dài hơn 10 năm chưa thể hoàn thành. Khu đất cũng nằm trong phạm vi xây dựng nhánh cầu nối đường này với cao tốc TP HCM - Long Thành - Dầu Giây, thuộc dự án nút giao An Phú vì vướng <a href="https://vnexpress.net/nut-giao-lon-nhat-tp-hcm-lui-tien-do-vi-vuong-2-2-ha-mat-bang-5095442.html">2,2 ha đất</a> của 67 hộ dân và tổ chức.</p>
  </div>
 </div>
</div>
<div>
 <div>
  <div>
   <img src="https://i1-vnexpress.vnecdn.net/2026/11/02/DJI-0581-1793599834-1793599840.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=-NqcCqK1ZJVNmKYH_uITgw">
  </div>
  <div>
   <p>Sau khi chấp thuận phương án bồi thường, nhiều hộ đã dỡ toàn bộ nhà hoặc lùi sâu để bàn giao mặt bằng thi công.</p>
   <p>Phần đất này liên quan đồng thời ba dự án gồm Khu đô thị Phát triển An Phú, mở rộng đường Lương Định Của và nút giao An Phú. Vướng mắc pháp lý trong bồi thường, giải phóng mặt bằng kéo dài hơn 10 năm qua, trở thành điểm nghẽn lớn nhất của các công trình trong khu vực.</p>
  </div>
 </div>
</div>
<div>
 <div>
  <div>
   <img src="https://i1-vnexpress.vnecdn.net/2026/11/02/DJI-0581-1793599834-1793599840.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=-NqcCqK1ZJVNmKYH_uITgw">
  </div>
 </div>
</div>
<div width="4729">
 <div>
  <div>
   <img alt="" src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-233a0932-1793600835-1793601102.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=3PAd2CFe4hImqHyyY5JwzA">
  </div>
  <div>
   <p>Tại một nhà xưởng rộng khoảng 500 m2 góc đường Mai Chí Thọ - Lương Định Của, máy cẩu và 5 công nhân tất bật phá dỡ, sáng 2/11.</p>
   <p>Theo Ban quản lý dự án đầu tư xây dựng phường Bình Trưng, tính đến ngày 1/11, có 54/67 trường hợp đồng thuận nhận tiền, bàn giao mặt bằng với diện tích hơn gần 13.000 m2.</p>
  </div>
 </div>
</div>
<div>
 <div>
  <div>
   <img src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-233A1098-1793598857-1793599211.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=OYs2XnFMsE9vqdU9seJ9hQ">
  </div>
  <div>
   <p>Công nhân tháo dỡ mái, cắt nhỏ các khối sắt thép, vật liệu xây dựng, thu dọn xà bần tại nhà xưởng.</p>
  </div>
 </div>
</div>
<div>
 <div>
  <div>
   <img src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-233A1028-1793598858-1793599211.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=Ed9tuBgJ8BDeB2pKCMoamA">
  </div>
 </div>
</div>
<div width="5472">
 <div>
  <div>
   <img alt="" src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-233a1233-1793600873-1793601102.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=HPs8cBC9tHCgPqPlNWq8vQ">
  </div>
  <div>
   <p>Những căn nhà san sát nhau huy động máy cẩu phá dỡ.</p>
   <p>Mức bồi thường được xác định theo loại đất như đất ở, nông nghiệp, kênh rạch và vị trí mặt tiền, hẻm. Cao nhất là đất ở mặt tiền đường Lương Định Của và Mai Chí Thọ, hơn 170 triệu đồng mỗi m2. Tổng kinh phí bồi thường cho 67 trường hợp hơn 1.800 tỷ đồng.</p>
  </div>
 </div>
</div>
<div width="5472">
 <div>
  <div>
   <img alt="" src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-233a1214-1793600917-1793601103.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=5EB_5-i2ILdb9xFVRWupwA">
  </div>
  <div>
   <p>Một võ đường ngổn ngang vật liệu xây dựng, xà bần sau khi tháo dỡ xong. Phần lớn dãy nhà ở mặt tiền đường Lương Định Của bị giải toả trắng.</p>
  </div>
 </div>
</div>
<div width="4653">
 <div>
  <div>
   <img alt="" src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-233a1170-1793600943-1793601103.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=eE3XjrHHlok3sAQPYdwpnQ">
  </div>
  <div>
   <p>Anh Minh Cảnh (phải) di chuyển những tấm tôn lợp mái nhà vào điểm tập kết. "Mấy hôm nay nơi này thi công rầm rộ lắm, trung bình mỗi nhà mất 2-3 ngày là dỡ xong", anh Cảnh nói.</p>
  </div>
 </div>
</div>
<div width="5472">
 <div>
  <div>
   <img alt="" src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-233a1074-1793600970-1793601104.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=PHQ-flAnMLR773QnBd84KA">
  </div>
  <div>
   <p>Ông Nguyễn Văn Thoại, 72 tuổi, bên căn nhà của mình, diện tích hơn 200 m2 chuẩn bị bàn giao trong vài ngày tới. Gia đình chấp nhận phương án bồi thường khoảng 34 tỷ đồng cùng một nền tái định cư.</p>
   <p>Hơn 50 năm ở đây, ông cho biết khu vực này thường xuyên ùn tắc, ngập nước nên người dân mong công trình sớm hoàn thành.</p>
  </div>
 </div>
</div>
<div>
 <div>
  <div>
   <img src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-233A1161-1793600180-1793601105.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=k1k7WJu9MpQ4_zbTfed_tw">
  </div>
  <div>
   <p>Nhiều chủ nhà sau khi hoàn tất hồ sơ đã dọn đi, để lại mặt bằng cho các đơn vị thi công.</p>
  </div>
 </div>
</div>
<div>
 <div>
  <div>
   <img src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-233A1131-1793600179-1793601104.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=lgCZCqncxdecsh5CApa8Zg">
  </div>
 </div>
</div>
<div width="5016">
 <div>
  <div>
   <img alt="" src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-dji-1793601019-1793601105.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=Bpu7gogPxc7WKcuR5qUU6w">
  </div>
  <div>
   <p>Đường Lương Định Của dài gần 2,5 km, từ Trần Não đến Nguyễn Thị Định, được mở rộng từ năm 2015 với tổng mức đầu tư khoảng 826 tỷ đồng. Đến nay, đoạn Nguyễn Hoàng - Trần Não đã hoàn thành, trong khi phần từ Nguyễn Hoàng đến Mai Chí Thọ vẫn dang dở, tạo thành nút thắt.</p>
  </div>
 </div>
</div>
<div width="2400">
 <div>
  <div>
   <img alt="" src="https://i1-vnexpress.vnecdn.net/2026/11/02/wm1-dji-0611-1793602241-1793602271.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=v5wLq7d7pvEK6nacxOQ9-w">
  </div>
  <div>
   <p>Nút giao An Phú nhìn từ hướng đường Lương Định Của. Khu vực này đang thi công nhánh cầu nối Lương Định Của với cao tốc TP HCM - Long Thành - Dầu Giây.</p>
   <p>Sau khi nhận mặt bằng, các chủ đầu tư sẽ có điều kiện triển khai những hạng mục còn lại của hai dự án, hoàn thiện hệ thống giao thông tại khu vực nút giao An Phú trong quý II/2027.</p>
   <p>Dự án khởi công năm 2022, tổng mức đầu tư hơn 3.400 tỷ đồng. Công trình có quy mô ba tầng, gồm hầm chui và nhiều cầu vượt kết nối các trục đường xung quanh.</p>
  </div>
 </div>
</div>
<div width="1198">
 <div>
  <div>
