INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7503, NULL, '2026-11-03 17:16:38.659503', 'Mẫu sedan cỡ lớn của thương hiệu BYD mang thiết kế vuông vức, kích thước nhỉnh hơn Ghost, ra mắt trong tháng 11.', 'https://i1-vnexpress.vnecdn.net/2026/11/02/yangwangaltior-1793607333-7253-1793607407.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=XH5AYoBi88OWoDhoDpDgVg', '2026-11-02 23:30:00', 'Yangwang Altior - xe của BYD cạnh tranh Rolls-Royce Ghost', 'https://vnexpress.net/yangwang-altior-xe-cua-byd-canh-tranh-rolls-royce-ghost-5139781.html', 1657, 9, 'https://vnexpress.net/yangwang-altior-xe-cua-byd-canh-tranh-rolls-royce-ghost-5139781.html', 'CRAWLER', '2026-11-03 17:18:00.443315', '2026-11-03 17:18:00.443315');;
