INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7510, NULL, '2026-11-03 17:16:39.937084', 'Người mua xe Lynk & Co trong tháng 11 nhận các ưu đãi lệ phí trước bạ, phụ kiện, bảo dưỡng và gói bảo hiểm thân vỏ chính hãng… trị giá hàng chục triệu đồng.', 'https://i1-vnexpress.vnecdn.net/2026/11/03/2-1793671410-4687-1793671491.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=u1LeG42x1V3xRGYrsg-ODA', '2026-11-03 03:00:00', 'Lynk & Co Việt Nam áp dụng loạt ưu đãi trong tháng 11', 'https://vnexpress.net/lynk-co-viet-nam-ap-dung-loat-uu-dai-trong-thang-11-5139958.html', 488, 9, 'https://vnexpress.net/lynk-co-viet-nam-ap-dung-loat-uu-dai-trong-thang-11-5139958.html', 'CRAWLER', '2026-11-03 17:17:09.293793', '2026-11-03 17:17:09.293793');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (8324, '<h1>Kim Biên là tên khác của thủ đô nước Đông Nam Á nào?</h1>
<p>Một địa danh Hán Việt từng xuất hiện trong tài liệu xưa, nhưng nay ít được sử dụng. Bạn có nhận ra thủ đô nào ẩn sau hai chữ này?</p>
<p>Đông Nam Á có nhiều thành phố mang những tên gọi khác nhau qua từng thời kỳ lịch sử. Một số tên bắt nguồn từ cách phiên âm Hán Việt, khiến người đọc ngày nay dễ cảm thấy xa lạ dù địa danh ấy vốn rất quen thuộc. "Kim Biên" là một ví dụ đáng chú ý.</p>
<p>Hai chữ này nghe như tên một vùng đất cổ, nhưng lại gắn với một thủ đô trong khu vực Đông Nam Á. Bạn có thể dựa vào kiến thức địa lý và lịch sử để tìm ra câu trả lời trước khi xem phần giải thích không?</p>
<figure>
 <div>
  <img alt="Tân Gia Ba là tên phiên âm Hán Việt của nước Đông Nam Á nào?" src="https://i1-vnexpress.vnecdn.net/2026/10/28/Document-1793156820-4836-1793156945.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=yLPqITtb1aLrv58gBGdcow">
 </div>
 <figcaption>
  <p>Kim Biên là tên khác của thủ đô nước Đông Nam Á nào? Minh họa: <em>Gemini</em></p>
 </figcaption>
</figure>
<p><a href="https://vnexpress.net/kim-bien-la-ten-khac-cua-thu-do-nuoc-dong-nam-a-nao-5137736-p2.html"><strong>&gt;&gt; Xem đáp án</strong></a></p>
<p><strong>Mộc Trà</strong></p><!-- Hope --> <!-- End Hope -->', '2026-11-03 17:20:26.950777', 'Một địa danh Hán Việt từng xuất hiện trong tài liệu xưa, nhưng nay ít được sử dụng. Bạn có nhận ra thủ đô nào ẩn sau hai chữ này?', 'https://i1-vnexpress.vnecdn.net/2026/10/28/document-1793156836-6968-1793156945.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=ciuN4qrKbAEG85IL018erQ', '2026-11-01 02:45:00', 'Kim Biên là tên khác của thủ đô nước Đông Nam Á nào?', 'https://vnexpress.net/kim-bien-la-ten-khac-cua-thu-do-nuoc-dong-nam-a-nao-5137736.html', 1331, 9, 'https://vnexpress.net/kim-bien-la-ten-khac-cua-thu-do-nuoc-dong-nam-a-nao-5137736.html', 'CRAWLER', '2026-11-03 17:20:26.950777', '2026-11-03 17:20:26.950777');;
