INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7541, NULL, '2026-11-03 17:16:45.243157', 'Nhìn chằm chằm vào chướng ngại khi đánh lái có thể khiến tài xế vô thức hướng xe về phía vật cản, thay vì khoảng trống an toàn.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/target-fixation-1793167959-7454-1793167978.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=u9JpeKhuIbI0UuB9PWjJRQ', '2026-10-29 23:00:00', 'Hiện tượng tài xế bị ''khóa mắt'' khi nhìn xe phía trước', 'https://vnexpress.net/hien-tuong-tai-xe-bi-khoa-mat-khi-nhin-xe-phia-truoc-5137856.html', 488, 9, 'https://vnexpress.net/hien-tuong-tai-xe-bi-khoa-mat-khi-nhin-xe-phia-truoc-5137856.html', 'CRAWLER', '2026-11-03 17:17:09.794023', '2026-11-03 17:17:09.794023');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (8327, '<p>Theo truyền thuyết dân gian Việt Nam, nguồn gốc dân tộc gắn với chuyện tình kỳ diệu giữa một vị thần thuộc nòi Rồng và một nàng tiên từ vùng núi. Hai người sinh ra 100 người con, được xem là tổ tiên chung của người Việt.</p>
<p>Sau này, 50 người con theo mẹ lên núi, 50 người theo cha xuống biển, cùng khai phá những vùng đất khác nhau. Người con trưởng được tôn lên làm vua, mở đầu truyền thuyết về các vua Hùng và thời đại Văn Lang. Câu chuyện còn lý giải cách gọi thân thương "đồng bào" của người Việt ngày nay. Vậy ai là người cha trong truyền thuyết ấy?</p>
<p><strong><a href="https://vnexpress.net/crossword-giai-o-chu-o-chu-thu-do-nuoc-dong-nam-a-nao-cung-ten-voi-quoc-gia-5131235.html">&gt;&gt; Thủ đô nước Đông Nam Á nào cùng tên với quốc gia?</a></strong></p>
<p><strong><a href="https://vnexpress.net/thu-gian/crossword">&gt;&gt; Thử giải những ô chữ khác</a></strong></p>
<p><strong>Hi</strong></p>', '2026-11-03 17:20:28.375978', 'Truyền thuyết ''Con Rồng cháu Tiên'' kể về 100 người con và sự hình thành cộng đồng người Việt. Bạn có nhớ ai giữ vai trò người cha trong chuyện?', 'https://i1-vnexpress.vnecdn.net/2026/10/26/4-1792984283-3469-1792984451.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=AR4b6wpXXh2CXjDBt-EHbQ', '2026-11-01 05:00:00', 'Theo truyền thuyết, ai là cha của các vua Hùng?', 'https://vnexpress.net/theo-truyen-thuyet-ai-la-cha-cua-cac-vua-hung-5136841.html', 1333, 9, 'https://vnexpress.net/theo-truyen-thuyet-ai-la-cha-cua-cac-vua-hung-5136841.html', 'CRAWLER', '2026-11-03 17:20:28.375978', '2026-11-03 17:20:28.375978');;
