INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7548, NULL, '2026-11-03 17:16:46.340133', 'Hình ảnh bằng sáng chế mới nhất hé lộ thiết kế ngoại thất của mẫu kei-car điện từ Emta, một liên doanh có sự tham gia của Chery.', 'https://i1-vnexpress.vnecdn.net/2026/10/29/Cherykeicar1-1793248045-5673-1793248079.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=XcZLGYvL2deuJKZ39adGVw', '2026-10-29 05:00:57', 'Chery làm kei-car điện để đấu BYD Racco', 'https://vnexpress.net/chery-lam-kei-car-dien-de-dau-byd-racco-5138195.html', 488, 9, 'https://vnexpress.net/chery-lam-kei-car-dien-de-dau-byd-racco-5138195.html', 'CRAWLER', '2026-11-03 17:17:10.898996', '2026-11-03 17:17:10.898996');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7549, NULL, '2026-11-03 17:16:46.433666', 'Sự cố cháy pin lithium trên xe đầu kéo Tesla khiến tuyến cao tốc I-880 ở bang California bị phong tỏa nhiều giờ do nguy cơ khói độc hại.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/Teslasemi1-1793175906-5023-1793176820.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=8z-uzs2sfNJMj_Itg51UpA', '2026-10-28 23:00:00', 'Cao tốc Mỹ bị phong tỏa để tránh khói độc từ xe điện cháy', 'https://vnexpress.net/cao-toc-my-bi-phong-toa-de-tranh-khoi-doc-tu-xe-dien-chay-5137936.html', 488, 9, 'https://vnexpress.net/cao-toc-my-bi-phong-toa-de-tranh-khoi-doc-tu-xe-dien-chay-5137936.html', 'CRAWLER', '2026-11-03 17:17:10.900994', '2026-11-03 17:17:10.900994');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (7550, NULL, '2026-11-03 17:16:46.524623', 'Người đàn ông Anh dành tình yêu đặc biệt cho thương hiệu ôtô Proton của Malaysia, sở hữu bộ sưu tập lên tới 34 chiếc.', 'https://i1-vnexpress.vnecdn.net/2026/10/28/ProtonSaga2-1793173672-6287-1793174624.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=VXJgUTeuJPYNTo30wvWX0A', '2026-10-28 22:00:00', 'Doanh nhân Anh sưu tầm gần 40 ôtô thương hiệu Đông Nam Á', 'https://vnexpress.net/doanh-nhan-anh-suu-tam-gan-40-oto-thuong-hieu-dong-nam-a-5137733.html', 488, 9, 'https://vnexpress.net/doanh-nhan-anh-suu-tam-gan-40-oto-thuong-hieu-dong-nam-a-5137733.html', 'CRAWLER', '2026-11-03 17:17:10.902995', '2026-11-03 17:17:10.902995');;
INSERT INTO public.articles (id, content, crawled_at, description, image_url, published_at, title, url, category_id, source_id, canonical_url, category_source, last_crawled_at, updated_at) VALUES (8378, '<!-- Bread Crumb --> <!-- END BREAD CRUMB -->
<div>
 <div>
